// Sort outputs by sortOrder (carousel slides can complete out of order)
const g = $input.first().json.generation;
const outputs = (g.outputs || [])
  .slice()
  .sort((a, b) => (a.sortOrder ?? 0) - (b.sortOrder ?? 0));

const lines = outputs.map((o, i) => `${i + 1}. ${o.format || 'visual'} — ${o.fileUrl}`);

const text = [
  `🎨 *New visuals ready* for "${g.title || 'your blog post'}"`,
  `${outputs.length} image(s)${g.status === 'partial' ? ' (some formats failed and were refunded)' : ''}:`,
  '',
  ...lines,
  '',
  `Review or edit: https://canvora.ai/generations/${g.id}`
].join('\n');

return [{ json: { text, outputs, generationId: g.id } }];
